   359	/** Initialize our pusher subscriptions to listen for someone leaving a room. */
   360	function subscribeToReportLeavingEvents(reportID: string) {
   361	    if (!reportID) {
   362	        return;
   363	    }
   364	
   365	    // Make sure we have a clean Leaving indicator before subscribing to leaving events
   366	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_LEAVING_ROOM}${reportID}`, false);
   367	
   368	    const pusherChannelName = getReportChannelName(reportID);
   369	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_LEAVING_ROOM, (leavingStatus: Pusher.UserIsLeavingRoomEvent) => {
   370	        // If the pusher message comes from OldDot, we expect the leaving status to be keyed by user
   371	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   372	        // since personal details are keyed by accountID.
   373	        const normalizedLeavingStatus = getNormalizedStatus(leavingStatus);
   374	        const accountIDOrLogin = Object.keys(normalizedLeavingStatus)[0];
   375	
   376	        if (!accountIDOrLogin) {
   377	            return;
   378	        }
   379	
   380	        if (Number(accountIDOrLogin) !== currentUserAccountID) {
   381	            return;
   382	        }
   383	
   384	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_LEAVING_ROOM}${reportID}`, true);
   385	    }).catch((error: ReportError) => {
   386	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   387	    });
   388	}
